<script setup lang="ts">import{onMounted,ref}from"vue";const p=defineProps<{apiBaseUrl:string}>(),state=ref("loading"),data=ref<any>({plans:[],assignment:null,adjustments:[],usage:{},effective_quotas:{}}),org=ref(new URLSearchParams(location.search).get("organization_id")??""),notice=ref(""),requestId=ref(""),plan=ref({code:"",name:"",description:"",collection_tasks:100,open_api_requests:1000,report_exports:20,reason:"商业配置变更"}),assignment=ref({plan_id:"",period_start:"",period_end:"",reason:"分配套餐"}),adjustment=ref({quota_key:"collection_tasks",delta_value:0,reason:"人工配额调整"}),pending=ref<any>(null);async function call(path:string,method="GET",body?:any){const r=await fetch(`${p.apiBaseUrl}${path}`,{method,credentials:"include",headers:{accept:"application/json","content-type":"application/json",origin:location.origin,"idempotency-key":crypto.randomUUID()},...(body?{body:JSON.stringify(body)}:{})}),j=await r.json();if(!r.ok){requestId.value=j.request_id??"";throw Object.assign(new Error(j.error?.message??"request_failed"),{status:r.status});}return j.data;}async function load(){state.value="loading";notice.value="";try{data.value=await call(`/platform/commercial${org.value?`?organization_id=${encodeURIComponent(org.value)}`:""}`);state.value=data.value.plans.length||data.value.assignment?"ready":"empty";}catch(e){notice.value=(e as Error).message;state.value=(e as any).status===429?"rate_limited":(e as any).status>=500?"blocked":"error";}}async function createPlan(){try{await call("/platform/commercial/plans","POST",{code:plan.value.code,name:plan.value.name,description:plan.value.description,quotas:{collection_tasks:Number(plan.value.collection_tasks),open_api_requests:Number(plan.value.open_api_requests),report_exports:Number(plan.value.report_exports)},reason:plan.value.reason});notice.value="套餐草稿已创建；启用前不影响任何组织。";await load();}catch(e){notice.value=(e as Error).message;}}function prepare(title:string,path:string,method:string,body:any){pending.value={title,path,method,body};}async function confirm(){if(!pending.value)return;const x=pending.value;pending.value=null;try{await call(x.path,x.method,x.body);notice.value="变更已写入审计。";await load();}catch(e){notice.value=(e as Error).message;}}const quotaNames:any={collection_tasks:"采集任务",open_api_requests:"开放 API 请求",report_exports:"报表导出"};onMounted(load);</script>
<template><section class="commercial"><header><div><p>COMMERCIAL OPERATIONS</p><h2>套餐、配额与用量</h2><span>仅管理版本化配额边界；不包含价格、支付扣款、发票或税务。</span></div><form @submit.prevent="load"><label>组织 UUID<input v-model="org" placeholder="查看或分配时填写"/></label><button>读取</button></form></header><p v-if="notice" class="commercial-notice">{{notice}} <code v-if="requestId">request_id: {{requestId}}</code></p><aside v-if="pending" class="commercial-confirm"><strong>确认{{pending.title}}？</strong><p>该变更会影响组织配额或套餐状态，并写入平台审计与事务事件。</p><button @click="pending=null">取消</button><button @click="confirm">确认执行</button></aside><section v-if="state==='loading'" class="commercial-state">正在读取真实套餐与用量…</section><section v-else-if="state==='error'" class="commercial-state"><strong>请求字段或组织范围无效</strong><button @click="load">修正后重试</button></section><section v-else-if="state==='rate_limited'" class="commercial-state"><strong>请求过于频繁</strong><button @click="load">稍后重试</button></section><section v-else-if="state==='blocked'" class="commercial-state"><strong>商业运营依赖受阻</strong><p>在宝塔检查 Node API 与 MySQL 后按 request_id 恢复。</p><button @click="load">检查恢复</button></section><template v-else><section class="commercial-create"><h3>创建套餐草稿</h3><label>代码<input v-model="plan.code"/></label><label>名称<input v-model="plan.name"/></label><label>采集任务<input v-model.number="plan.collection_tasks" type="number" min="0"/></label><label>开放 API<input v-model.number="plan.open_api_requests" type="number" min="0"/></label><label>报表导出<input v-model.number="plan.report_exports" type="number" min="0"/></label><button @click="createPlan">创建草稿</button></section><p v-if="state==='empty'" class="commercial-state">暂无套餐定义。系统不会自动编造默认价格或配额。</p><section class="commercial-plans"><article v-for="x in data.plans" :key="x.id" :data-status="x.status"><header><span>{{x.status}}</span><h3>{{x.name}}</h3><code>{{x.code}} · v{{x.version}}</code></header><p>{{x.description||'未填写说明'}}</p><dl><div v-for="(n,k) in x.quotas" :key="k"><dt>{{quotaNames[k]||k}}</dt><dd>{{n}}</dd></div></dl><button v-if="x.status==='draft'" @click="prepare('启用套餐',`/platform/commercial/plans/${x.id}`,'PATCH',{name:x.name,description:x.description,quotas:x.quotas,status:'active',expected_version:x.version,reason:plan.reason})">启用</button><button v-else-if="x.status==='active'" @click="prepare('退役套餐',`/platform/commercial/plans/${x.id}`,'PATCH',{name:x.name,description:x.description,quotas:x.quotas,status:'retired',expected_version:x.version,reason:plan.reason})">退役</button></article></section><section v-if="org" class="commercial-org"><header><h3>组织套餐与本账期用量</h3><small>{{org}}</small></header><form v-if="!data.assignment"><label>套餐<select v-model="assignment.plan_id"><option value="">选择已启用套餐</option><option v-for="x in data.plans.filter((p:any)=>p.status==='active')" :key="x.id" :value="x.id">{{x.name}}</option></select></label><label>开始<input v-model="assignment.period_start" type="datetime-local"/></label><label>结束<input v-model="assignment.period_end" type="datetime-local"/></label><button type="button" @click="prepare('分配套餐','/platform/commercial/assignments','POST',{organization_id:org,...assignment})">分配</button></form><template v-else><div class="commercial-assignment"><div><strong>{{data.assignment.plan_name}}</strong><small>{{data.assignment.status}} · {{data.assignment.period_start}} — {{data.assignment.period_end}}</small></div><button v-if="data.assignment.status==='active'" @click="prepare('暂停组织套餐',`/platform/commercial/assignments/${data.assignment.id}/actions`,'POST',{action:'suspend',expected_version:data.assignment.version,reason:assignment.reason})">暂停</button><button v-else-if="data.assignment.status==='suspended'" @click="prepare('恢复组织套餐',`/platform/commercial/assignments/${data.assignment.id}/actions`,'POST',{action:'resume',expected_version:data.assignment.version,reason:assignment.reason})">恢复</button></div><div class="commercial-usage"><article v-for="(limit,key) in data.effective_quotas" :key="key"><span>{{quotaNames[key]||key}}</span><strong>{{data.usage[key]||0}} / {{limit}}</strong><b><i :style="{width:`${Math.min(100,limit?((data.usage[key]||0)/Number(limit))*100:100)}%`}"></i></b></article></div><form class="commercial-adjust"><label>计量项<select v-model="adjustment.quota_key"><option v-for="(_,k) in data.effective_quotas" :key="k" :value="k">{{quotaNames[k]||k}}</option></select></label><label>调整量<input v-model.number="adjustment.delta_value" type="number"/></label><label>原因<input v-model="adjustment.reason"/></label><button type="button" @click="prepare('人工调整配额','/platform/commercial/adjustments','POST',{organization_id:org,assignment_id:data.assignment.id,...adjustment})">提交调整</button></form><ul class="commercial-adjustments"><li v-for="x in data.adjustments" :key="x.id"><span>{{quotaNames[x.quota_key]}} {{x.delta_value>0?'+':''}}{{x.delta_value}}</span><small>{{x.reason}} · {{x.status}}</small><button v-if="x.status==='active'" @click="prepare('撤销人工调整',`/platform/commercial/adjustments/${x.id}/revoke`,'POST',{expected_version:x.version,reason:'撤销人工调整'})">撤销</button></li></ul></template></section></template></section></template>
